import json,base64,gzip,pathlib,sqlite3,subprocess,shutil,datetime,urllib.request,time
root=pathlib.Path('/opt/agricola4')
backup=root/'releases'/('before-gym-stats-'+datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%SZ'))
backup.mkdir(parents=True)
files=json.loads(gzip.decompress(base64.b64decode('')))
for name in [*files,'Caddyfile']:
    if (root/name).exists():shutil.copy2(root/name,backup/name)
with sqlite3.connect('/var/lib/agricola4/scores.sqlite3') as src,sqlite3.connect(backup/'scores.sqlite3') as dest:src.backup(dest)
def read():return json.load(urllib.request.urlopen('http://127.0.0.1:8001/api/submissions',timeout=30))
before=read();(backup/'before.json').write_text(json.dumps(before,ensure_ascii=False))
try:
    config=(root/'Caddyfile').read_text()
    lines=config.splitlines()
    index=next(i for i,line in enumerate(lines) if line.strip().startswith('@api path '))
    if '/api/players/gym' not in lines[index].split():lines[index]+=' /api/players/gym'
    candidate=root/'Caddyfile.gym-candidate';candidate.write_text('\n'.join(lines)+'\n')
    subprocess.run(['/usr/local/bin/caddy','validate','--config',str(candidate),'--adapter','caddyfile'],check=True)
    for name,content in files.items():(root/name).write_text(content,encoding='utf-8')
    shutil.copy2(candidate,root/'Caddyfile')
    subprocess.run([str(root/'.venv/bin/python'),'-m','unittest','-q'],cwd=root,check=True)
    subprocess.run(['chown','agricola:agricola',*[str(root/name) for name in files]],check=True)
    subprocess.run(['systemctl','restart','agricola4'],check=True)
    subprocess.run(['systemctl','reload','agricola-caddy'],check=True)
    for attempt in range(10):
        try:after=read();break
        except Exception:
            if attempt==9:raise
            time.sleep(1)
    for board in ('global','season'):
        assert len(before['rankings'][board])==len(after['rankings'][board])
        for old,new in zip(before['rankings'][board],after['rankings'][board]):
            assert old=={k:new[k] for k in old},'Existing rating fields changed: '+old['name']
    assert before['items']==after['items'],'Match records changed'
    assert before['prizes']==after['prizes'],'Prize data changed'
    assert all(p['globalMaxComplete'] and p['globalStatsGames']==p['globalGames'] for p in after['rankings']['global'])
    request=urllib.request.Request('https://140.143.126.83/api/players/gym',method='OPTIONS',headers={'Origin':'https://huang-yuxiao.github.io'})
    response=urllib.request.urlopen(request,timeout=20)
    assert response.status==204 and response.headers.get('Access-Control-Allow-Origin')=='https://huang-yuxiao.github.io'
    (backup/'after.json').write_text(json.dumps(after,ensure_ascii=False))
except Exception:
    for name in [*files,'Caddyfile']:
        if (backup/name).exists():shutil.copy2(backup/name,root/name)
    subprocess.run(['systemctl','restart','agricola4'])
    subprocess.run(['systemctl','reload','agricola-caddy'])
    raise
print('GYM_STATS_DEPLOY_OK',after['rankings']['count'],'matches',len(after['rankings']['global']),'players')
print('EXISTING_ELO_MATCHES_PRIZES_UNCHANGED; BACKUP',backup)
